#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("punkty.txt");
    int n;
    plik >> n;
    int q1 = 0, q2 = 0, q3 = 0, q4 = 0, os = 0;
    for (int i = 0; i < n; i++) {
        int x, y;
        plik >> x >> y;
        if (x > 0 && y > 0) q1++;
        else if (x < 0 && y > 0) q2++;
        else if (x < 0 && y < 0) q3++;
        else if (x > 0 && y < 0) q4++;
        else os++;
    }
    cout << "Kwadrant I: " << q1 << endl;
    cout << "Kwadrant II: " << q2 << endl;
    cout << "Kwadrant III: " << q3 << endl;
    cout << "Kwadrant IV: " << q4 << endl;
    cout << "Na osiach: " << os << endl;
    return 0;
}
```

Weryfikacja:
- I (x>0,y>0): (3,4),(1,1) = 2
- II (x<0,y>0): (-2,5),(-4,1) = 2
- III (x<0,y<0): (-1,-3),(-3,-4) = 2
- IV (x>0,y<0): (4,-2),(2,-6) = 2
- Osie: (0,3),(5,0) = 2
